/*
 * dsentry_protocol.h -- the D-Sentry wire format: the four framed packets (ControlPacket,
 * StatusPacket, TelemetryPacket, BeaconPacket), their enums and bit masks, the D-Sentry AT
 * command names, CRC-8/SMBUS, encoders, decoders and one streaming deframer for all four.
 *
 * GENERATED by D-SentryCode/tools/gen_protocol.py from D-SentryCode/protocol/protocol_spec.py.
 * Do not edit: change protocol_spec.py, run tools/gen_protocol.py and commit every output.
 * Byte-identical copies (gen_protocol.py --check fails while either is stale):
 *   D-SentryCode/protocol/dsentry_protocol.h     canonical; the RA4M1 sketch symlinks to it
 *   firmware/UNOR4USBBridge/dsentry_protocol.h   the ESP32-S3 fork's copy
 * Offsets, enums, AT commands and example frames: D-SentryCode/docs/protocol.md.
 *
 * Frame: start | len | payload[len] | crc. len counts the payload only; crc is CRC-8/SMBUS
 * (poly 0x07, init 0x00, no reflection, no xor-out) over len and the payload.
 * A frame is accepted only with one of the four start bytes, that type's exact len and a
 * matching CRC, so ASCII debug text on the same USB port can never be taken for one.
 *
 * Byte order: little-endian. Each payload struct is packed and laid out exactly as on the
 * wire (static_asserts below pin every size and offset), so the encoders and decoders memcpy
 * it. That is correct only on a little-endian CPU: the RA4M1 (Cortex-M4), the ESP32-S3
 * (Xtensa LX7) and the Mac all are, and a static_assert refuses to compile anywhere else.
 * Access packed fields by value (p.rx = v); do not take their address.
 * Plain C99 (gnu99/gnu11) and C++11..17; no dynamic allocation, no globals, no Arduino headers.
 *
 * SPDX-License-Identifier: MIT
 * Copyright (c) 2026 the D-Sentry project
 */
#pragma once
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <stdbool.h>

/* static_assert for C++11, C11 and plain C99 (where a negative array size stops the build) */
#if defined(__cplusplus)
#define DS_STATIC_ASSERT(cond, msg) static_assert(cond, msg)
#elif defined(__STDC_VERSION__) && __STDC_VERSION__ >= 201112L
#define DS_STATIC_ASSERT(cond, msg) _Static_assert(cond, msg)
#else
#define DS_STATIC_ASSERT_JOIN2_(a, b) a##b
#define DS_STATIC_ASSERT_JOIN_(a, b) DS_STATIC_ASSERT_JOIN2_(a, b)
#define DS_STATIC_ASSERT(cond, msg) \
  typedef char DS_STATIC_ASSERT_JOIN_(ds_static_assert_line_, __LINE__)[(cond) ? 1 : -1]
#endif

#if !defined(__BYTE_ORDER__) || !defined(__ORDER_LITTLE_ENDIAN__)
#error "dsentry_protocol.h: cannot tell the byte order; the codecs memcpy little-endian structs"
#endif
DS_STATIC_ASSERT(__BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__,
                 "dsentry_protocol.h memcpys packed structs: little-endian CPUs only");

/* ---- versions and scales ---- */
/* D-Sentry protocol version; AT+DSCAPS? reports it as dsProto. */
#define DS_PROTO_VERSION       1
/* TelemetryPacket.version; a receiver that sees another value must not trust the fields. */
#define DS_TELEMETRY_VERSION   2
/* Wire units per degree. Angles are centidegrees (deg * 100), angular rates centidegrees/s. */
#define DS_ANGLE_SCALE         100
#define DS_TELEMETRY_LCD_ROWS  2    /* Rows of the LCD mirrored in TelemetryPacket.lcd. */
#define DS_TELEMETRY_LCD_COLS  16   /* Characters per mirrored LCD row (space padded). */
/* TelemetryPacket.padBattery when the source reports no level (= XBOX_R4_BATTERY_UNKNOWN). */
#define DS_PAD_BATTERY_UNKNOWN 255

/* ---- framing ---- */
#define DS_FRAME_HEADER_LEN 2      /* start + len */
#define DS_FRAME_OVERHEAD   3      /* start + len + crc */
#define DS_MAX_PAYLOAD_LEN  107    /* largest len of any packet */
#define DS_MAX_FRAME_LEN    110    /* largest frame of any packet */
#define DS_CRC8_POLY        0x07u  /* CRC-8/SMBUS */
#define DS_CRC8_INIT        0x00u
#define DS_CRC8_CHECK       0xF4u  /* CRC of the ASCII bytes "123456789" */

/* Packet type ids: what ds_deframer_feed() reports. 0 = no frame completed. */
#define DS_PKT_NONE      0
#define DS_PKT_CONTROL   1  /* ControlPacket */
#define DS_PKT_STATUS    2  /* StatusPacket */
#define DS_PKT_TELEMETRY 3  /* TelemetryPacket */
#define DS_PKT_BEACON    4  /* BeaconPacket */
#define DS_PKT_COUNT     5  /* including DS_PKT_NONE */

#define DS_CONTROL_START     0xA5  /* ControlPacket start byte */
#define DS_CONTROL_LEN       10    /* payload bytes = the len byte */
#define DS_CONTROL_FRAME_LEN 13    /* start + len + payload + crc */

#define DS_STATUS_START     0x5A  /* StatusPacket start byte */
#define DS_STATUS_LEN       7     /* payload bytes = the len byte */
#define DS_STATUS_FRAME_LEN 10    /* start + len + payload + crc */

#define DS_TELEMETRY_START     0xD5  /* TelemetryPacket start byte */
#define DS_TELEMETRY_LEN       107   /* payload bytes = the len byte */
#define DS_TELEMETRY_FRAME_LEN 110   /* start + len + payload + crc */
#define DS_TELEMETRY_LCD_LEN   32    /* TelemetryPacket.lcd elements */

#define DS_BEACON_START     0xD6  /* BeaconPacket start byte */
#define DS_BEACON_LEN       8     /* payload bytes = the len byte */
#define DS_BEACON_FRAME_LEN 11    /* start + len + payload + crc */
#define DS_BEACON_IP_LEN    4     /* BeaconPacket.ip elements */

/* ---- enums (one byte on the wire) ---- */
/* TurretState: Top-level state of the RA4M1 state machine (spec 3.1, architecture.md 6). */
/* power toggle open: steppers disabled, flywheel 0, servo detached, LEDs dark */
#define DS_STATE_OFF         0
#define DS_STATE_BOOT        1  /* peripherals starting; lasts one tick after begin() */
#define DS_STATE_CALIBRATING 2  /* tilt homing */
#define DS_STATE_PAIRING     3  /* waiting for a connected control source */
#define DS_STATE_DISARMED    4  /* connected; motion allowed, trigger and flywheels locked */
#define DS_STATE_ARMED       5  /* connected; flywheels and firing allowed */
#define DS_STATE_FAULT       6  /* calibration or stall fault (see Fault) */
#define DS_STATE_COUNT       7  /* values 0..COUNT-1 */

/* Fault: Why the turret is in FAULT (TelemetryPacket.fault). */
#define DS_FAULT_NONE  0  /* no fault */
#define DS_FAULT_CAL   1  /* calibration failed; clears only by toggling power */
#define DS_FAULT_STALL 2  /* stall detected; clears after STALL_FAULT_HOLD_MS */
#define DS_FAULT_COUNT 3  /* values 0..COUNT-1 */

/* RadioMode: Radio the RA4M1 wants the ESP32 to run (StatusPacket.wantMode, AT+DSS wantMode).
 * Mirrors the BT/WiFi toggle on A1. */
#define DS_RADIO_BLE   0  /* the turret pairs directly with the pad over BLE */
#define DS_RADIO_WIFI  1  /* the PC relay holds the pad and sends ControlPackets over UDP */
#define DS_RADIO_COUNT 2  /* values 0..COUNT-1 */

/* EspMode: Radio the ESP32 reports running (AT+DSS reply espMode, TelemetryPacket.espMode). */
#define DS_ESP_MODE_BLE        0    /* BLE client running */
#define DS_ESP_MODE_WIFI       1    /* WiFi station or access point running */
#define DS_ESP_MODE_NONE       2    /* no D-Sentry radio started yet */
/* the other radio was running; the ESP32 stored the wanted mode and restarts into it about 50 ms
 * after this reply */
#define DS_ESP_MODE_RESTARTING 3
#define DS_ESP_MODE_UNKNOWN    255  /* RA4M1 side only: no DSS reply yet, or legacy firmware */

/* LinkSource: Which input the RA4M1 is obeying (TelemetryPacket.linkSource). USB wins while a valid
 * USB ControlPacket arrived within LINK_TIMEOUT_MS (architecture.md 4.3). */
#define DS_LINK_SRC_NONE  0  /* no live source */
#define DS_LINK_SRC_BLE   1  /* the pad over BLE, through AT+XBOXSTATE? */
#define DS_LINK_SRC_WIFI  2  /* the PC relay over UDP, through AT+XBOXSTATE? */
#define DS_LINK_SRC_USB   3  /* ControlPackets over the USB serial port (bench override) */
#define DS_LINK_SRC_COUNT 4  /* values 0..COUNT-1 */

/* PadState: Controller connection state (TelemetryPacket.padState). BLE source: the AT+XBOXSTATE?
 * state byte (byte 16, enum xbox_r4_conn_state in protocol/xbox_r4_protocol.h) as sent; WiFi
 * source: the same byte, which the ESP32 sets to 0 or 3; USB source: 0 when the ControlPacket says
 * connected, else 3. */
/* reports flowing (BLE), or the source says connected (WiFi, USB) */
#define DS_PAD_STATE_CONNECTED            0
/* BLE link up, encryption or subscription in progress */
#define DS_PAD_STATE_WAITING_FIRST_REPORT 1
#define DS_PAD_STATE_FOUND                2    /* BLE: the pad was seen in a scan, connecting */
/* BLE: no pad connected, scanning; WiFi or USB: the source is not connected */
#define DS_PAD_STATE_SCANNING             3
#define DS_PAD_STATE_OFF                  4    /* BLE: the ESP32's Xbox client is not running */
/* BLE: the ArduinoBLE HCI bridge owns the radio until AT+RESET */
#define DS_PAD_STATE_BLOCKED_BY_HCI       5
/* no control source: no frame arrived within LINK_TIMEOUT_MS */
#define DS_PAD_STATE_NONE                 255

/* FireMode: Trigger behaviour, toggled by B (TelemetryPacket.fireMode). */
#define DS_FIRE_MODE_SEMI  0  /* one stroke per pull */
#define DS_FIRE_MODE_FULL  1  /* strokes back-to-back while the trigger is held */
#define DS_FIRE_MODE_COUNT 2  /* values 0..COUNT-1 */

/* WifiStatus: ESP32 WiFi state (AT+DSS reply wifiStatus, BeaconPacket.mode). */
#define DS_WIFI_STATUS_OFF         0  /* WiFi not running */
#define DS_WIFI_STATUS_CONNECTING  1  /* station connecting */
#define DS_WIFI_STATUS_STATION_UP  2  /* joined WIFI_SSID as a station */
#define DS_WIFI_STATUS_AP_UP       3  /* hosting its own access point WIFI_AP_SSID */
/* a valid ControlPacket arrived from the relay within LINK_TIMEOUT_MS */
#define DS_WIFI_STATUS_RELAY_HEARD 4
#define DS_WIFI_STATUS_COUNT       5  /* values 0..COUNT-1 */

/* DstResult: AT+DST reply. */
/* not forwarded: not in WiFi mode, no relay address yet, or the hex was not exactly one valid
 * TelemetryPacket */
#define DS_DST_NOT_SENT 0
#define DS_DST_SENT     1  /* forwarded by UDP to the relay */
#define DS_DST_COUNT    2  /* values 0..COUNT-1 */

/* ---- bit masks ---- */
/* ControlFlags (8-bit): ControlPacket.flags. */
/* bit 0: a controller (pad or keyboard) is live; 0 = neutral input, no source */
#define DS_CTRL_FLAG_CONNECTED   0x01u
#define DS_CTRL_FLAG_SOURCE_WIFI 0x02u  /* bit 1: source: 0 = BLE, 1 = WiFi (the relay) */
#define DS_CTRL_FLAG_ESP_PAIRING 0x04u  /* bit 2: the ESP32 is in pairing mode */
/* bit 3: the relay's dashboard keyboard is driving, not a pad */
#define DS_CTRL_FLAG_KEYBOARD    0x08u
#define DS_CTRL_FLAG_ALL         0x0Fu  /* every defined bit */

/* Buttons (16-bit): ControlPacket.buttons and TelemetryPacket.padButtons (spec 3.2 mapping: A arm,
 * B semi/full, X magazine, d-pad left set home, d-pad down go home; Menu enters SERVO ADJUST from
 * DISARMED, where d-pad up/down, RB/LB, A, B, View and X set the trigger servo angles instead and
 * Menu saves and leaves, TurretState.h). Bits 12-15 exist for the dashboard's controller view: a
 * ControlPacket may carry them and the RA4M1 never acts on them. */
#define DS_BTN_A          0x0001u  /* bit 0: A: toggle ARMED/DISARMED */
#define DS_BTN_B          0x0002u  /* bit 1: B: toggle semi/full */
#define DS_BTN_X          0x0004u  /* bit 2: X: reset magazine to MAG_CAPACITY */
#define DS_BTN_Y          0x0008u  /* bit 3: Y: unused */
#define DS_BTN_LB         0x0010u  /* bit 4: left bumper: flywheels */
#define DS_BTN_RB         0x0020u  /* bit 5: right bumper: unused */
#define DS_BTN_DPAD_UP    0x0040u  /* bit 6: d-pad up: unused */
#define DS_BTN_DPAD_DOWN  0x0080u  /* bit 7: d-pad down: go home */
#define DS_BTN_DPAD_LEFT  0x0100u  /* bit 8: d-pad left: set home */
#define DS_BTN_DPAD_RIGHT 0x0200u  /* bit 9: d-pad right: unused */
/* bit 10: Menu (start): servo adjust when DISARMED (enter / save and leave) */
#define DS_BTN_START      0x0400u
/* bit 11: View (back): in servo adjust, config.h's REST / FIRE back in force; else unused */
#define DS_BTN_BACK       0x0800u
/* bit 12: left stick click: shown on the dashboard, no turret action */
#define DS_BTN_LS_CLICK   0x1000u
#define DS_BTN_RS_CLICK   0x2000u  /* bit 13: right stick click: shown, no turret action */
#define DS_BTN_XBOX       0x4000u  /* bit 14: Xbox (guide) button: shown, no turret action */
#define DS_BTN_SHARE      0x8000u  /* bit 15: Share button: shown, no turret action */
#define DS_BTN_ALL        0xFFFFu  /* every defined bit */

/* TelemetryFlags (16-bit): TelemetryPacket.flags. */
#define DS_TELEM_FLAG_LINK_CONNECTED      0x0001u  /* bit 0: a control source is connected */
/* bit 1: flywheel commanded on (ramping or at duty) */
#define DS_TELEM_FLAG_FLYWHEEL_ON         0x0002u
/* bit 2: flywheel on for at least FLYWHEEL_SPINUP_MS */
#define DS_TELEM_FLAG_FLYWHEEL_READY      0x0004u
#define DS_TELEM_FLAG_STROKE_ACTIVE       0x0008u  /* bit 3: a trigger stroke is in progress */
/* bit 4: trigger reads pulled (hysteresis applied) */
#define DS_TELEM_FLAG_TRIGGER_PULLED      0x0010u
#define DS_TELEM_FLAG_HOMING              0x0020u  /* bit 5: a go-home position move is running */
/* bit 6: tilt calibration finished; tilt bounds active */
#define DS_TELEM_FLAG_CALIBRATED          0x0040u
#define DS_TELEM_FLAG_POWER_TOGGLE_ON     0x0080u  /* bit 7: power toggle (A0) reads on */
#define DS_TELEM_FLAG_MODE_TOGGLE_WIFI    0x0100u  /* bit 8: mode toggle (A1) reads WiFi */
#define DS_TELEM_FLAG_STALL_ENABLED       0x0200u  /* bit 9: stall detector active */
/* bit 10: empty-magazine double flash showing (ammo 0, DISARMED/ARMED) */
#define DS_TELEM_FLAG_EMPTY_MAG_BLINK     0x0400u
#define DS_TELEM_FLAG_DRIVERS_ENABLED     0x0800u  /* bit 11: stepper drivers enabled (EN low) */
/* bit 12: the ESP32 answered AT+DSCAPS? with ERROR (old fork/stock) */
#define DS_TELEM_FLAG_ESP_LEGACY_FIRMWARE 0x1000u
#define DS_TELEM_FLAG_LCD_PRESENT         0x2000u  /* bit 13: an LCD answered on I2C */
/* bit 14: the ESP32 answered within LINK_TIMEOUT_MS */
#define DS_TELEM_FLAG_ESP_ALIVE           0x4000u
#define DS_TELEM_FLAG_ALL                 0x7FFFu  /* every defined bit */

/* Caps (8-bit): AT+DSCAPS? capBits: what the ESP32 firmware supports. */
#define DS_CAP_RUMBLE    0x01u  /* bit 0: rumble in BLE mode (AT+DSS rumble fields reach the pad) */
#define DS_CAP_WIFI      0x02u  /* bit 1: WiFi mode (station/AP, UDP ControlPackets) */
#define DS_CAP_MODE      0x04u  /* bit 2: radio switching through AT+DSS wantMode */
#define DS_CAP_TELEMETRY 0x08u  /* bit 3: AT+DST forwarding to the relay */
#define DS_CAP_ALL       0x0Fu  /* every defined bit */

/* ---- D-Sentry AT commands (Serial2, chAT server on the ESP32). Every command answers with
 * its prompt and OK; failures go in the payload. Arguments and reply fields are decimal
 * unless marked hex. The RA4M1 sends "AT" NAME ("?" | "=" args) "\r\n". ---- */
/* AT+DSCAPS?  ->  +DSCAPS: <dsProto>,<capBits> */
#define DS_AT_DSCAPS                "+DSCAPS"
#define DS_AT_DSCAPS_ARGC           0          /* arguments */
#define DS_AT_DSCAPS_REPLY_COUNT    2          /* reply fields */
#define DS_AT_DSCAPS_REPLY_DS_PROTO 0          /* u8: the firmware's DS_PROTO_VERSION */
#define DS_AT_DSCAPS_REPLY_CAP_BITS 1          /* u8: DS_CAP_* bits */

/* AT+DSS=<wantMode>,<rumbleSeq>,<strong>,<weak>,<rumbleMs>,<state> -> +DSS:
 * <espMode>,<bootId>,<wifiStatus> */
#define DS_AT_DSS                   "+DSS"
#define DS_AT_DSS_ARGC              6       /* arguments */
#define DS_AT_DSS_ARG_WANT_MODE     0       /* u8: DS_RADIO_*: radio to run */
/* u8: StatusPacket.rumbleSeq; a new value starts the rumble below */
#define DS_AT_DSS_ARG_RUMBLE_SEQ    1
#define DS_AT_DSS_ARG_STRONG        2       /* u8: StatusPacket.rumbleStrong, 0..255 */
#define DS_AT_DSS_ARG_WEAK          3       /* u8: StatusPacket.rumbleWeak, 0..255 */
#define DS_AT_DSS_ARG_RUMBLE_MS     4       /* u16: StatusPacket.rumbleMs; 0 = stop */
/* u8: DS_STATE_*: turret state, for the ESP32's own log */
#define DS_AT_DSS_ARG_STATE         5
#define DS_AT_DSS_REPLY_COUNT       3       /* reply fields */
/* u8: DS_ESP_MODE_*: radio running now (3 = restarting into wantMode) */
#define DS_AT_DSS_REPLY_ESP_MODE    0
/* u8: random non-zero byte chosen at ESP32 boot; a change means it rebooted */
#define DS_AT_DSS_REPLY_BOOT_ID     1
#define DS_AT_DSS_REPLY_WIFI_STATUS 2       /* u8: DS_WIFI_STATUS_* */

/* AT+DST=<hex>  ->  +DST: <sent> */
#define DS_AT_DST             "+DST"
#define DS_AT_DST_ARGC        1       /* arguments */
/* hex: one complete TelemetryPacket frame (start..crc), 2 hex digits per byte */
#define DS_AT_DST_ARG_HEX     0
#define DS_AT_DST_REPLY_COUNT 1       /* reply fields */
#define DS_AT_DST_REPLY_SENT  0       /* u8: DS_DST_*: 1 = forwarded by UDP to the relay, 0 = not */

/* hex digits of one TelemetryPacket in AT+DST */
#define DS_AT_DST_HEX_LEN  (2 * DS_TELEMETRY_FRAME_LEN)
/* "AT+DST=" + hex + "\r\n" (229 bytes) */
#define DS_AT_DST_LINE_LEN (sizeof("AT" DS_AT_DST "=") - 1 + DS_AT_DST_HEX_LEN + 2)

/* ---- payload structs: exactly the wire layout of the bytes between len and crc ---- */

/* ControlPacket 0xA5, payload 10 bytes, frame 13 bytes.
 * Controller input (spec 5). Stick up is negative (the Bluepad32/SDL convention); the RA4M1
 * applies JOY_INVERT_Y.
 */
typedef struct __attribute__((packed)) ds_control_packet {
  uint8_t  flags;    /*  0: DS_CTRL_FLAG_* bits */
  int16_t  rx;       /*  1: right stick X, -512..511, right positive */
  int16_t  ry;       /*  3: right stick Y, -512..511, up negative */
  uint16_t rt;       /*  5: right trigger, 0..1023 */
  uint16_t buttons;  /*  7: DS_BTN_* bits */
  /* 9: increments per packet, wraps; the RA4M1 counts gaps and echoes it in
   * TelemetryPacket.lastCtrlSeq */
  uint8_t  seq;
} ds_control_packet_t;
DS_STATIC_ASSERT(sizeof(ds_control_packet_t) == DS_CONTROL_LEN, "ControlPacket payload size");
DS_STATIC_ASSERT(offsetof(ds_control_packet_t, flags) == 0, "ControlPacket.flags offset");
DS_STATIC_ASSERT(offsetof(ds_control_packet_t, rx) == 1, "ControlPacket.rx offset");
DS_STATIC_ASSERT(offsetof(ds_control_packet_t, ry) == 3, "ControlPacket.ry offset");
DS_STATIC_ASSERT(offsetof(ds_control_packet_t, rt) == 5, "ControlPacket.rt offset");
DS_STATIC_ASSERT(offsetof(ds_control_packet_t, buttons) == 7, "ControlPacket.buttons offset");
DS_STATIC_ASSERT(offsetof(ds_control_packet_t, seq) == 9, "ControlPacket.seq offset");

/* StatusPacket 0x5A, payload 7 bytes, frame 10 bytes.
 * Turret status and rumble requests (spec 5, plus rumbleSeq).
 */
typedef struct __attribute__((packed)) ds_status_packet {
  uint8_t  wantMode;      /*  0: radio the RA4M1 wants (mirrors the A1 toggle) */
  uint8_t  rumbleStrong;  /*  1: strong (low-frequency) motor, 0..255 */
  uint8_t  rumbleWeak;    /*  2: weak (high-frequency) motor, 0..255 */
  uint16_t rumbleMs;      /*  3: rumble length in ms; 0 = stop */
  uint8_t  state;         /*  5: turret state */
  /* 6: increments on every new rumble command, so a heartbeat repeat is not a new shot */
  uint8_t  rumbleSeq;
} ds_status_packet_t;
DS_STATIC_ASSERT(sizeof(ds_status_packet_t) == DS_STATUS_LEN, "StatusPacket payload size");
DS_STATIC_ASSERT(offsetof(ds_status_packet_t, wantMode) == 0, "StatusPacket.wantMode offset");
DS_STATIC_ASSERT(offsetof(ds_status_packet_t, rumbleStrong) == 1,
                 "StatusPacket.rumbleStrong offset");
DS_STATIC_ASSERT(offsetof(ds_status_packet_t, rumbleWeak) == 2, "StatusPacket.rumbleWeak offset");
DS_STATIC_ASSERT(offsetof(ds_status_packet_t, rumbleMs) == 3, "StatusPacket.rumbleMs offset");
DS_STATIC_ASSERT(offsetof(ds_status_packet_t, state) == 5, "StatusPacket.state offset");
DS_STATIC_ASSERT(offsetof(ds_status_packet_t, rumbleSeq) == 6, "StatusPacket.rumbleSeq offset");

/* TelemetryPacket 0xD5, payload 107 bytes, frame 110 bytes.
 * Everything the dashboard shows. Start byte >= 0x80 so it is never ASCII. Pan: positive =
 * counter-clockwise seen from above (stick right turns the turret clockwise, i.e. negative;
 * PAN_DIR_INVERT fixes the hardware side). Tilt: 0 = calibrated bottom plus backoff, positive =
 * barrel up.
 * Version 2 (DS_TELEMETRY_VERSION). Fields marked vN were appended by version N; older layouts
 * (version 1 = len 91) end before them. This header encodes, decodes and deframes the current
 * layout only; the PC relay also reads the older ones.
 */
typedef struct __attribute__((packed)) ds_telemetry_packet {
  uint8_t  version;                    /*  0: DS_TELEMETRY_VERSION */
  uint8_t  seq;                        /*  1: increments per TelemetryPacket, wraps */
  uint32_t uptimeMs;                   /*  2: RA4M1 millis() when built */
  uint8_t  state;                      /*  6: turret state */
  uint8_t  fault;                      /*  7: fault code */
  uint8_t  fireMode;                   /*  8: 0 semi, 1 full */
  uint8_t  linkSource;                 /*  9: active control source */
  uint16_t flags;                      /* 10: DS_TELEM_FLAG_* bits */
  int32_t  panCdeg;                    /* 12: pan position, centidegrees, + = CCW from above */
  int32_t  tiltCdeg;                   /* 16: tilt position, centidegrees, + = up */
  int16_t  panVelCdegS;                /* 20: pan velocity, centidegrees/s */
  int16_t  tiltVelCdegS;               /* 22: tilt velocity, centidegrees/s */
  int32_t  homePanCdeg;                /* 24: stored home pan, centidegrees */
  int32_t  homeTiltCdeg;               /* 28: stored home tilt, centidegrees */
  uint8_t  ammo;                       /* 32: darts left */
  uint8_t  magCapacity;                /* 33: MAG_CAPACITY */
  uint16_t shotsTotal;                 /* 34: strokes completed since boot, wraps */
  uint8_t  flywheelDuty;               /* 36: ENA duty now, 0..255 */
  uint8_t  servoDeg;                   /* 37: trigger servo commanded angle, degrees */
  uint16_t stallSample;                /* 38: latest A2 reading, ADC counts */
  uint16_t stallBaseline;              /* 40: stall EMA baseline, ADC counts */
  /* 42: largest |sample - baseline| of the current or last move, ADC counts */
  uint16_t stallPeak;
  uint16_t loopHz;                     /* 44: loop() iterations per second, saturates */
  /* 46: valid control frames per second from the active source */
  uint16_t ctrlRxHz;
  uint16_t crcErrors;                  /* 48: control-path CRC errors since boot, wraps */
  uint16_t seqGaps;                    /* 50: control seq gaps since boot, wraps */
  /* 52: worst step jitter of the last stats window, permille of the step period */
  uint16_t stepJitterPermille;
  /* 54: seq of the last accepted ControlPacket (echo for round-trip latency) */
  uint8_t  lastCtrlSeq;
  uint8_t  espMode;                    /* 55: radio the ESP32 reports */
  uint8_t  ledR;                       /* 56: LED 0 red as sent, after the brightness clamp */
  uint8_t  ledG;                       /* 57: LED 0 green as sent */
  uint8_t  ledB;                       /* 58: LED 0 blue as sent */
  char     lcd[DS_TELEMETRY_LCD_LEN];  /* 59: LCD text, row 0 then row 1, space padded */
  uint8_t  padState;                   /* 91: v2: controller connection state */
  /* 92: v2: pad battery percent 0..100 (AT+XBOXSTATE? byte 17), 255 = unknown */
  uint8_t  padBattery;
  /* 93: v2: left stick X, -512..511, right positive (BLE only, else 0) */
  int16_t  padLx;
  /* 95: v2: left stick Y, -512..511, up negative (BLE only, else 0) */
  int16_t  padLy;
  int16_t  padRx;                      /* 97: v2: right stick X as received, right positive */
  int16_t  padRy;                      /* 99: v2: right stick Y as received, up negative */
  uint16_t padLt;                      /* 101: v2: left trigger, 0..1023 (BLE only, else 0) */
  uint16_t padRt;                      /* 103: v2: right trigger as received, 0..1023 */
  /* 105: v2: DS_BTN_* levels as received, bits 12-15 included */
  uint16_t padButtons;
} ds_telemetry_packet_t;
