/* BeaconPacket 0xD6, payload 8 bytes, frame 11 bytes.
 * WiFi discovery. The relay listens on WIFI_DISCOVERY_PORT when no --udp host is given.
 */
typedef struct __attribute__((packed)) ds_beacon_packet {
  /* 0: the turret's IPv4 address, first octet first (192.168.4.1 = c0 a8 04 01) */
  uint8_t  ip[DS_BEACON_IP_LEN];
  uint16_t udpPort;               /*  4: where to send ControlPackets (WIFI_UDP_PORT) */
  uint8_t  bootId;                /*  6: random non-zero byte chosen at ESP32 boot */
  uint8_t  mode;                  /*  7: WiFi status: 2 station, 3 own AP, 4 relay heard */
} ds_beacon_packet_t;
DS_STATIC_ASSERT(sizeof(ds_beacon_packet_t) == DS_BEACON_LEN, "BeaconPacket payload size");
DS_STATIC_ASSERT(offsetof(ds_beacon_packet_t, ip) == 0, "BeaconPacket.ip offset");
DS_STATIC_ASSERT(offsetof(ds_beacon_packet_t, udpPort) == 4, "BeaconPacket.udpPort offset");
DS_STATIC_ASSERT(offsetof(ds_beacon_packet_t, bootId) == 6, "BeaconPacket.bootId offset");
DS_STATIC_ASSERT(offsetof(ds_beacon_packet_t, mode) == 7, "BeaconPacket.mode offset");

/* ---- CRC-8/SMBUS ---- */
static inline uint8_t ds_crc8_update(uint8_t crc, uint8_t byte) {
  crc = (uint8_t)(crc ^ byte);
  for (int bit = 0; bit < 8; bit++) {
    crc = (uint8_t)((crc & 0x80u) ? ((unsigned)(crc << 1) ^ DS_CRC8_POLY) : (unsigned)(crc << 1));
  }
  return crc;
}

static inline uint8_t ds_crc8(const uint8_t* data, size_t len) {
  uint8_t crc = DS_CRC8_INIT;
  for (size_t i = 0; i < len; i++) crc = ds_crc8_update(crc, data[i]);
  return crc;
}

/* ---- per-type lookups ---- */
/* DS_PKT_* for a start byte, or DS_PKT_NONE. */
static inline uint8_t ds_packet_type_for_start(uint8_t start) {
  switch (start) {
    case DS_CONTROL_START: return DS_PKT_CONTROL;
    case DS_STATUS_START: return DS_PKT_STATUS;
    case DS_TELEMETRY_START: return DS_PKT_TELEMETRY;
    case DS_BEACON_START: return DS_PKT_BEACON;
    default: return DS_PKT_NONE;
  }
}

/* Start byte of a DS_PKT_* type, or 0 for DS_PKT_NONE / unknown. */
static inline uint8_t ds_start_for_type(uint8_t type) {
  switch (type) {
    case DS_PKT_CONTROL: return DS_CONTROL_START;
    case DS_PKT_STATUS: return DS_STATUS_START;
    case DS_PKT_TELEMETRY: return DS_TELEMETRY_START;
    case DS_PKT_BEACON: return DS_BEACON_START;
    default: return 0;
  }
}

/* Exact payload length (the len byte) of a DS_PKT_* type, or 0. */
static inline uint8_t ds_payload_len_for_type(uint8_t type) {
  switch (type) {
    case DS_PKT_CONTROL: return DS_CONTROL_LEN;
    case DS_PKT_STATUS: return DS_STATUS_LEN;
    case DS_PKT_TELEMETRY: return DS_TELEMETRY_LEN;
    case DS_PKT_BEACON: return DS_BEACON_LEN;
    default: return 0;
  }
}

/* Whole frame length of a DS_PKT_* type, or 0. */
static inline uint8_t ds_frame_len_for_type(uint8_t type) {
  uint8_t len = ds_payload_len_for_type(type);
  return len ? (uint8_t)(len + DS_FRAME_OVERHEAD) : (uint8_t)0;
}

static inline const char* ds_packet_type_name(uint8_t type) {
  switch (type) {
    case DS_PKT_NONE: return "none";
    case DS_PKT_CONTROL: return "ControlPacket";
    case DS_PKT_STATUS: return "StatusPacket";
    case DS_PKT_TELEMETRY: return "TelemetryPacket";
    case DS_PKT_BEACON: return "BeaconPacket";
    default: return "?";
  }
}

/* True when frame[0..len) is one complete, valid frame of the given type: exact length,
 * start byte, len byte and CRC. */
static inline bool ds_frame_check(const uint8_t* frame, size_t len, uint8_t type) {
  uint8_t payload = ds_payload_len_for_type(type);
  if (payload == 0 || frame == NULL) return false;
  if (len != (size_t)payload + DS_FRAME_OVERHEAD) return false;
  if (frame[0] != ds_start_for_type(type) || frame[1] != payload) return false;
  return ds_crc8(frame + 1, (size_t)payload + 1) == frame[len - 1];
}

/* Writes start, len and crc around a payload already copied to out + DS_FRAME_HEADER_LEN. */
static inline size_t ds_frame_finish(uint8_t* out, uint8_t type) {
  uint8_t payload = ds_payload_len_for_type(type);
  out[0] = ds_start_for_type(type);
  out[1] = payload;
  out[DS_FRAME_HEADER_LEN + payload] = ds_crc8(out + 1, (size_t)payload + 1);
  return (size_t)payload + DS_FRAME_OVERHEAD;
}

/* ---- encoders, decoders, initialisers ----
 * ds_<pkt>_init(p)               zeroes p and applies the spec's defaults
 * ds_<pkt>_encode(p, out)        writes the whole frame to out, returns its length
 * ds_<pkt>_decode(frame, len, p) true and fills p only for one exact, valid frame */

static inline void ds_control_init(ds_control_packet_t* p) {
  memset(p, 0, sizeof *p);
}

static inline size_t ds_control_encode(const ds_control_packet_t* p,
                                       uint8_t out[DS_CONTROL_FRAME_LEN]) {
  memcpy(out + DS_FRAME_HEADER_LEN, p, DS_CONTROL_LEN);
  return ds_frame_finish(out, DS_PKT_CONTROL);
}

static inline bool ds_control_decode(const uint8_t* frame, size_t len, ds_control_packet_t* p) {
  if (!ds_frame_check(frame, len, DS_PKT_CONTROL)) return false;
  memcpy(p, frame + DS_FRAME_HEADER_LEN, DS_CONTROL_LEN);
  return true;
}

static inline void ds_status_init(ds_status_packet_t* p) {
  memset(p, 0, sizeof *p);
}

static inline size_t ds_status_encode(const ds_status_packet_t* p,
                                      uint8_t out[DS_STATUS_FRAME_LEN]) {
  memcpy(out + DS_FRAME_HEADER_LEN, p, DS_STATUS_LEN);
  return ds_frame_finish(out, DS_PKT_STATUS);
}

static inline bool ds_status_decode(const uint8_t* frame, size_t len, ds_status_packet_t* p) {
  if (!ds_frame_check(frame, len, DS_PKT_STATUS)) return false;
  memcpy(p, frame + DS_FRAME_HEADER_LEN, DS_STATUS_LEN);
  return true;
}

