/* ---- streaming deframer (all four packet types on one byte stream) ----
 * Feed every received byte; when a frame completes, feed() returns its DS_PKT_* type and
 * ds_deframer_frame() / ds_deframer_frame_len() give its bytes (start..crc) until the next
 * feed() or poll(). Acceptance (architecture.md 4.1): one of the four start bytes, that
 * type's exact len, matching CRC. On any mismatch only the first held byte is dropped (counted
 * as junk) and the search restarts at the next one, so a frame that began inside a rejected
 * candidate is still found. In that rare case one fed byte can expose more than one frame:
 * the later ones are reported by the following calls, so after draining the input call
 * ds_deframer_poll() until it returns DS_PKT_NONE. Every byte not in an accepted frame is
 * counted in junk_bytes (debug text included). At most DS_MAX_FRAME_LEN bytes are held.
 * Cost: a memmove of the held bytes per dropped byte; text bytes cost almost nothing. */
typedef struct ds_deframer {
  uint8_t  buf[DS_MAX_FRAME_LEN];
  uint8_t  held;        /* bytes in buf, including a frame reported by the last call */
  uint8_t  ready_len;   /* >0: buf[0..ready_len) is the frame the last call reported */
  uint8_t  ready_type;  /* its DS_PKT_* type */
  uint32_t frames;      /* frames accepted */
  uint32_t crc_errors;  /* candidates with a start byte and the right len but a bad CRC */
  uint32_t len_errors;  /* start bytes followed by the wrong len (text 'Z' lands here) */
  uint32_t junk_bytes;  /* bytes that were not part of an accepted frame */
} ds_deframer_t;

static inline void ds_deframer_init(ds_deframer_t* d) {
  memset(d, 0, sizeof *d);
}

/* internal: forget the first count held bytes */
static inline void ds_deframer_drop_(ds_deframer_t* d, uint8_t count) {
  memmove(d->buf, d->buf + count, (size_t)(d->held - count));
  d->held = (uint8_t)(d->held - count);
}

/* internal: resolve held bytes until a frame completes or more bytes are needed */
static inline uint8_t ds_deframer_settle_(ds_deframer_t* d) {
  while (d->held > 0) {
    uint8_t type = ds_packet_type_for_start(d->buf[0]);
    if (type == DS_PKT_NONE) {
      d->junk_bytes++;
      ds_deframer_drop_(d, 1);
      continue;
    }
    if (d->held < DS_FRAME_HEADER_LEN) return DS_PKT_NONE;
    if (d->buf[1] != ds_payload_len_for_type(type)) {
      d->len_errors++;
      d->junk_bytes++;
      ds_deframer_drop_(d, 1);
      continue;
    }
    uint8_t n = ds_frame_len_for_type(type);
    if (d->held < n) return DS_PKT_NONE;
    if (ds_crc8(d->buf + 1, (size_t)n - 2) != d->buf[n - 1]) {
      d->crc_errors++;
      d->junk_bytes++;
      ds_deframer_drop_(d, 1);
      continue;
    }
    d->frames++;
    d->ready_len = n;
    d->ready_type = type;
    return type;
  }
  return DS_PKT_NONE;
}

/* internal: release the frame the previous call reported */
static inline void ds_deframer_release_(ds_deframer_t* d) {
  if (d->ready_len) {
    ds_deframer_drop_(d, d->ready_len);
    d->ready_len = 0;
    d->ready_type = DS_PKT_NONE;
  }
}

/* Feed one received byte. Returns the DS_PKT_* type of a frame that completed, or
 * DS_PKT_NONE. */
static inline uint8_t ds_deframer_feed(ds_deframer_t* d, uint8_t byte) {
  ds_deframer_release_(d);
  /* Never true: after settle_() the held bytes are a frame or a strict prefix of one. */
  if (d->held >= DS_MAX_FRAME_LEN) {
    d->junk_bytes++;
    ds_deframer_drop_(d, 1);
  }
  d->buf[d->held++] = byte;
  return ds_deframer_settle_(d);
}

/* Report a further frame already held (see above), without new input. */
static inline uint8_t ds_deframer_poll(ds_deframer_t* d) {
  ds_deframer_release_(d);
  return ds_deframer_settle_(d);
}

/* The frame the last feed()/poll() reported (start..crc), or NULL. */
static inline const uint8_t* ds_deframer_frame(const ds_deframer_t* d) {
  return d->ready_len ? d->buf : NULL;
}

static inline uint8_t ds_deframer_frame_len(const ds_deframer_t* d) {
  return d->ready_len;
}

/* ---- hex for AT+DST ---- */
/* Writes 2*len lowercase hex digits and a NUL to out (2*len + 1 chars). Returns 2*len. */
static inline size_t ds_hex_encode(const uint8_t* data, size_t len, char* out) {
  static const char digits[] = "0123456789abcdef";
  for (size_t i = 0; i < len; i++) {
    out[2 * i] = digits[data[i] >> 4];
    out[2 * i + 1] = digits[data[i] & 0x0Fu];
  }
  out[2 * len] = '\0';
  return 2 * len;
}

/* Value of one hex digit (either case), or -1. */
static inline int ds_hex_digit(char c) {
  if (c >= '0' && c <= '9') return c - '0';
  if (c >= 'a' && c <= 'f') return c - 'a' + 10;
  if (c >= 'A' && c <= 'F') return c - 'A' + 10;
  return -1;
}

/* Parses hex_len hex digits (either case) into out. Returns the byte count, or 0 when
 * hex_len is odd or zero, a character is not a hex digit, or the bytes do not fit in cap. */
static inline size_t ds_hex_decode(const char* hex, size_t hex_len, uint8_t* out, size_t cap) {
  if (hex_len == 0 || (hex_len & 1u) || hex_len / 2 > cap) return 0;
  for (size_t i = 0; i < hex_len / 2; i++) {
    int hi = ds_hex_digit(hex[2 * i]);
    int lo = ds_hex_digit(hex[2 * i + 1]);
    if (hi < 0 || lo < 0) return 0;
    out[i] = (uint8_t)((hi << 4) | lo);
  }
  return hex_len / 2;
}

